// ===================== SETTINGS (safe to change) =====================
const PROMPT_VERSION = 'v1';          // which prompt files to use: outline.<format>.v1.md
const MODEL = 'gpt-4.1-mini';         // OpenAI model used for the outline
const REPO_RAW = 'https://raw.githubusercontent.com/mysteriouslyscentedtyrant/lead-magnet-generator/main';
// =====================================================================

const FORMATS = ['ebook', 'guide', 'checklist'];
const TONES = ['friendly', 'professional', 'bold', 'inspiring', 'conversational'];
const LENGTHS = ['short', 'standard', 'detailed'];

const body = $input.first().json.body || {};
const errors = [];

// Removes invisible/control characters, angle brackets and {{ }} so user text
// can't break out of the <user_input> tags or inject placeholders.
function clean(value) {
  if (typeof value !== 'string') return '';
  return value
    .normalize('NFKC')
    .replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200F\u2028-\u202E\u2060-\u2069\uFEFF]/g, ' ')
    .replace(/[<>]/g, ' ')
    .replace(/\{\{|\}\}/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function text(field, label, min, max) {
  const v = clean(body[field]);
  if (v.length < min) errors.push(`${label} must be at least ${min} characters.`);
  else if (v.length > max) errors.push(`${label} must be ${max} characters or less.`);
  return v;
}

function choice(field, label, allowed, fallback) {
  const raw = body[field];
  if (raw === undefined || raw === null || raw === '') {
    if (fallback !== undefined) return fallback;
    errors.push(`${label} is required.`);
    return '';
  }
  const v = String(raw).trim().toLowerCase();
  if (!allowed.includes(v)) {
    errors.push(`${label} must be one of: ${allowed.join(', ')}.`);
    return '';
  }
  return v;
}

const format = choice('format', 'Format', FORMATS);
const topic = text('topic', 'Topic', 3, 200);
const audience = text('audience', 'Audience', 3, 400);
const tone = choice('tone', 'Tone', TONES, 'friendly');
const length = choice('length', 'Length', LENGTHS, 'standard');

let language = clean(body.language || '') || 'English';
if (!/^[\p{L} ()-]{2,30}$/u.test(language)) {
  errors.push('Language must be a language name such as English or French.');
}

if (errors.length) {
  return [{
    json: {
      ok: false,
      response: { ok: false, code: 'invalid_input', message: errors.join(' ') },
    },
  }];
}

return [{
  json: {
    ok: true,
    input: { format, topic, audience, tone, length, language },
    model: MODEL,
    promptVersion: PROMPT_VERSION,
    promptUrl: `${REPO_RAW}/prompts/outline.${format}.${PROMPT_VERSION}.md`,
    schemaUrl: `${REPO_RAW}/schema/outline.response.schema.json`,
  },
}];

// Builds the OpenAI request from the prompt file and response schema loaded from GitHub.
const settings = $('Validate input').first().json;
const input = settings.input;
const promptText = String($('Load prompt').first().json.data || '').replace(/\r\n/g, '\n');
const schemaText = $('Load schema').first().json.data;

// Split the prompt file into its SYSTEM and USER parts.
const sysMarker = '===SYSTEM===';
const userMarker = '===USER===';
const sysAt = promptText.indexOf(sysMarker);
const userAt = promptText.indexOf(userMarker);
if (sysAt === -1 || userAt === -1 || userAt < sysAt) {
  throw new Error('Prompt file is missing the ===SYSTEM=== or ===USER=== marker: ' + settings.promptUrl);
}
const system = promptText.slice(sysAt + sysMarker.length, userAt).trim();
const userTemplate = promptText.slice(userAt + userMarker.length).trim();

// Fill {{placeholders}} in ONE pass, so text typed by a user is never re-read as a placeholder.
const user = userTemplate.replace(/\{\{(\w+)\}\}/g, (match, key) => {
  if (!(key in input)) throw new Error('Prompt uses an unknown placeholder: ' + match);
  return input[key];
});

let responseSchema;
try {
  responseSchema = typeof schemaText === 'string' ? JSON.parse(schemaText) : schemaText;
} catch (e) {
  throw new Error('Response schema is not valid JSON: ' + settings.schemaUrl);
}

return [{
  json: {
    requestBody: {
      model: settings.model,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
      response_format: { type: 'json_schema', json_schema: responseSchema },
      max_completion_tokens: 3000,
    },
  },
}];

// Checks the AI answer and turns it into the document shape used by the frontend.
// Any problem throws an error -> the workflow answers with a generic "please try again".
const settings = $('Validate input').first().json;
const input = settings.input;
const res = $input.first().json;

const choice = res.choices && res.choices[0];
const message = choice && choice.message;
if (!message) throw new Error('OpenAI returned no message: ' + JSON.stringify(res).slice(0, 500));
if (choice.finish_reason === 'length') throw new Error('Outline was cut off (max_completion_tokens too low).');

function rejected(reason) {
  return [{
    json: {
      response: {
        ok: false,
        code: 'rejected',
        message: reason || "We can't create a lead magnet on this topic. Please try a different one.",
      },
    },
  }];
}

if (message.refusal) return rejected();

let data;
try {
  data = JSON.parse(message.content);
} catch (e) {
  throw new Error('AI answer is not valid JSON: ' + String(message.content).slice(0, 500));
}

// ---------- text helpers ----------
function tidy(value) {
  return String(value == null ? '' : value)
    .replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200F\u2028-\u202E\u2060-\u2069\uFEFF]/g, ' ')
    .replace(/\*\*|__|`/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}
function cut(value, max) {
  const v = tidy(value);
  if (v.length <= max) return v;
  const short = v.slice(0, max);
  const space = short.lastIndexOf(' ');
  return (space > max * 0.6 ? short.slice(0, space) : short).replace(/[\s,;:.-]+$/, '');
}
function heading(value) {
  return cut(String(value || '').replace(/^\s*(#+|\d+[.)]|[-*\u2022])\s*/, ''), 90);
}

if (data.status === 'rejected') return rejected(cut(data.reason, 200));
if (data.status !== 'ok') throw new Error('Unexpected status: ' + data.status);

// ---------- structure rules per format ----------
const RULES = {
  ebook:     { first: ['intro'],   middle: 'chapter', last: ['conclusion'],            min: 4, max: 7 },
  guide:     { first: ['problem'], middle: 'step',    last: ['mistakes', 'next_step'], min: 3, max: 9 },
  checklist: { first: [],          middle: 'group',   last: [],                        min: 3, max: 5 },
};
const rule = RULES[input.format];
const raw = Array.isArray(data.sections) ? data.sections : [];
const types = raw.map(s => s && s.type);
const middleCount = types.length - rule.first.length - rule.last.length;
const expected = [...rule.first, ...Array(Math.max(middleCount, 0)).fill(rule.middle), ...rule.last];

if (middleCount < rule.min || middleCount > rule.max || types.join() !== expected.join()) {
  throw new Error(`Outline structure is wrong for ${input.format}: [${types.join(', ')}]`);
}

const sections = raw.map((s, i) => ({
  id: 's' + (i + 1),
  type: s.type,
  heading: heading(s.heading),
  goal: cut(s.goal, 200),
  keyPoints: (Array.isArray(s.keyPoints) ? s.keyPoints : [])
    .map(k => cut(String(k).replace(/^\s*(\d+[.)]|[-*\u2022]|\[ ?\])\s*/, ''), 160))
    .filter(Boolean)
    .slice(0, 8),
  status: 'outlined',
  blocks: [],
}));

if (sections.some(s => s.heading.length < 2)) throw new Error('A section heading is empty or too short.');

// A checklist must fit on one page: keep at most 20 items in total.
if (input.format === 'checklist') {
  let total = sections.reduce((n, s) => n + s.keyPoints.length, 0);
  while (total > 20) {
    const biggest = sections.reduce((a, b) => (b.keyPoints.length > a.keyPoints.length ? b : a));
    biggest.keyPoints.pop();
    total--;
  }
}

const title = cut(data.title, 90);
if (!title) throw new Error('Outline has no title.');

const cta = data.cta || {};

return [{
  json: {
    response: {
      ok: true,
      // The frontend adds "branding" before preview/PDF.
      document: {
        schemaVersion: '1.0',
        format: input.format,
        meta: {
          topic: input.topic,
          audience: input.audience,
          tone: input.tone,
          length: input.length,
          language: input.language,
        },
        title,
        subtitle: cut(data.subtitle, 160),
        sections,
        cta: {
          heading: cut(cta.heading, 90),
          text: cut(cta.text, 400),
          buttonLabel: cut(cta.buttonLabel, 40),
          url: '',
        },
      },
      generator: {
        promptVersion: settings.promptVersion,
        model: res.model || settings.model,
        tokens: res.usage ? res.usage.total_tokens : null,
      },
    },
  },
}];
